/// <summary>
/// Caches whether a product is marked "Priced by Weight" to avoid repeated database lookups.
/// </summary>
public class METPricedByWeightCache
{
}

Method.Source:
/// <summary>
/// Retrieves the "Priced by weight" attribute value for a given item.
/// </summary>
/// <param name="_itemId">
/// The unique identifier of the item (Product Number) whose attribute value is being checked.
/// </param>
/// <returns>
/// A boolean value indicating whether the item is priced by weight:
/// - true  → Item is priced by weight
/// - false → Item is not priced by weight or attribute not found
/// </returns>
/// <remarks>
/// The method queries the EcoResProductAttributeValueEntity table to find the BooleanValue
/// associated with the "Priced by weight" attribute for the specified item.
/// If the attribute exists, its BooleanValue is returned; otherwise, false is returned.
/// </remarks>
public static boolean getPricedByWeightAttributeCached(ItemId _itemId)
{
    if (!_itemId) return false;
    if (!FeatureStateProvider::isFeatureEnabled(METPricedByWeightCacheFeature::instance()))
        return SalesLineSalesPurchLine::getPricedByWeightAttributeValue(_itemId);

    SysGlobalObjectCache cache = classFactory.globalObjectCache();
    container            key   = [_itemId];   // no company component — EcoRes attribute data is global
    str                  scope = '@MET:METPricedByWeight';
    container cached = cache.find(scope, key);
    if (cached) return conPeek(cached, 1);

    boolean         pbw       = false;
    EcoResProduct   product   = EcoResProduct::findByProductNumber(_itemId);
    EcoResAttribute attribute = EcoResAttribute::findByName(
    METConstants::PricedByWeightAttributeId,
    EcoResAttributeType::findByName(METConstants::EcoResAttributeTypeBoolean).RecId);
    if (product && attribute)
    {
        EcoResBooleanValue          boolValue;
        EcoResProductAttributeValue prodAttrValue;
        select firstOnly BooleanValue from boolValue
            exists join prodAttrValue
            where prodAttrValue.Value     == boolValue.RecId    // RecId joins (indexed)
                && prodAttrValue.Product   == product.RecId
                && prodAttrValue.Attribute == attribute.RecId;
            pbw = boolValue.BooleanValue;
    }
    cache.insert(scope, key, [pbw]);
    return pbw;
}

/// <summary>
/// Gets the RecId of the EcoRes attribute used to indicate an item is "Priced by weight".
/// </summary>
/// <returns>
/// The RecId of the matching <c>EcoResAttribute</c> for the "Priced by weight" attribute.
/// </returns>
public static RecId pricedByWeightAttributeRecId()
{
    return EcoResAttribute::findByName(METConstants::PricedByWeightAttributeId,EcoResAttributeType::findByName(METConstants::EcoResAttributeTypeBoolean).RecId).RecId;
}
